/* AEGIS terrain, drawn live on a canvas instead of played as a pre-rendered video.
   Data: assets/aegis-terrain-data.png (103 KB) holds, per grid vertex,
     top half    R,G = elevation in metres (16-bit)   B = 255 when the vertex faces the camera
     bottom half R,G = the frozen 20x ridged-noise horizontal offset (16-bit)
   Everything else is arithmetic, so the render is resolution independent and loops seamlessly. */
(function () {
  /* Terrain data inlined as a data: URI so the canvas is never tainted and the page
     works from file:// as well as from a server. */
  var DATA_URI = 'data:image/png;base64,';
  var M = {
    cols: 224, rows: 126, step: 6.454972243679028,
    hmin: -25.227511518815998, hmax: 269.2816253043579,
    omin: -144.49501037597656, omax: 69.46793365478516,
    centerM: 15.007494106676097, vexag: 16.0, mpp: 6.666666666666667,
    W: 960, H: 540,
    r00: 0.984807753012208, r01: 0.0593911746138847, r02: 0.16317591116653482,
    r10: 0.0, r11: 0.9396926207859084, r12: -0.3420201433256687,
    G_ENTRY: 0.5, G_REVMORPH0: 0.1, G_REVMORPH1: 0.6, G_TERRAIN0: 0.6,
    G_MORPH0: 3.6, G_MORPH1: 4.1, G_EXIT0: 3.8, RATE: 5.0
  };
  /* Re-cut loop: play the tail backwards, then the body. Both ends meet at the fully scattered
     state and the terrain wave has an exact 3 s period, so the wrap is continuous. */
  var G_END = 140 / 30, HEAD = 32 / 30, LOOP = 154 / 30;
  function gAt(tau) { return tau < HEAD ? (G_END - tau) : (M.G_TERRAIN0 + (tau - HEAD)); }
  function ease(q) { return q * q * q * (q * (q * 6 - 15) + 10); }        /* smootherstep */
  function morphAt(g) {
    if (g < M.G_REVMORPH0) return -1;
    if (g < M.G_REVMORPH1) return -ease((M.G_REVMORPH1 - g) / (M.G_REVMORPH1 - M.G_REVMORPH0));
    if (g < M.G_MORPH0) return 0;
    if (g < M.G_MORPH1) return ease((g - M.G_MORPH0) / (M.G_MORPH1 - M.G_MORPH0));
    return 1;
  }
  function mulberry(seed) {                                              /* small seeded PRNG */
    return function () {
      seed |= 0; seed = seed + 0x6D2B79F5 | 0;
      var t = Math.imul(seed ^ seed >>> 15, 1 | seed);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  var section = document.querySelector('.aegis-sec');
  var canvas = section && section.querySelector('.aegis-terrain-canvas');
  if (!canvas) return;
  var ctx = canvas.getContext('2d', { alpha: false });
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
  var conn = navigator.connection || navigator.mozConnection || navigator.webkitConnection;

  var N = 0, PX = null, PY = null, HGT = null, OFF = null, PH = null, EB = null, IB = null;
  var ready = false, near = false, vis = false, raf = 0, t0 = 0, cw = 0, ch = 0, scale = 1, ox = 0, oy = 0;

  function decode(img) {
    var c = document.createElement('canvas');
    c.width = M.cols; c.height = M.rows * 2;
    var g = c.getContext('2d'); g.drawImage(img, 0, 0);
    var d = g.getImageData(0, 0, M.cols, M.rows * 2).data;
    var half = M.cols * M.rows, keep = [];
    for (var i = 0; i < half; i++) if (d[i * 4 + 2] > 127) keep.push(i);
    N = keep.length;
    PX = new Float32Array(N); PY = new Float32Array(N); HGT = new Float32Array(N);
    OFF = new Float32Array(N); PH = new Float32Array(N);
    var hs = (M.hmax - M.hmin) / 65535, os = (M.omax - M.omin) / 65535;
    for (var k = 0; k < N; k++) {
      var idx = keep[k], col = idx % M.cols, row = (idx / M.cols) | 0, p = idx * 4, q = (half + idx) * 4;
      var hM = M.hmin + (d[p] * 256 + d[p + 1]) * hs;
      var x0 = col * M.step, y0 = row * M.step;
      PX[k] = x0; PY[k] = y0; HGT[k] = (hM - M.centerM) * M.vexag / M.mpp;
      OFF[k] = M.omin + (d[q] * 256 + d[q + 1]) * os;
      PH[k] = x0 * 0.006 + y0 * 0.008 + hM * 0.018;
    }
    var re = mulberry(8123), ri = mulberry(2244);
    EB = new Float32Array(N); IB = new Float32Array(N);
    for (var j = 0; j < N; j++) { EB[j] = 14 + re() * 36; IB[j] = 100 + ri() * 260; }
    ready = true;
  }

  var imgData = null, u32 = null, gray = null, MAXW = 1600;
  function resize() {
    var r = canvas.getBoundingClientRect();
    if (!r.width || !r.height) return;
    var dpr = Math.min(window.devicePixelRatio || 1, 1.5);
    var w = r.width * dpr;
    if (w > MAXW) dpr *= MAXW / w;                        /* cap the backing store */
    cw = Math.max(1, Math.round(r.width * dpr)); ch = Math.max(1, Math.round(r.height * dpr));
    canvas.width = cw; canvas.height = ch;
    scale = Math.max(cw / M.W, ch / M.H);                 /* object-fit: cover */
    ox = (cw - M.W * scale) / 2; oy = (ch - M.H * scale) / 2;
    imgData = ctx.createImageData(cw, ch);                /* allocated once, reused per frame */
    u32 = new Uint32Array(imgData.data.buffer);
    gray = new Uint8ClampedArray(cw * ch);
  }

  function draw(tau) {
    if (!imgData) return;
    var g = gAt(tau), m = morphAt(g), t = (g - M.G_TERRAIN0) / 3 * Math.PI * 2;
    var exitOn = g > M.G_EXIT0 ? Math.exp(M.RATE * (g - M.G_EXIT0)) - 1 : 0;
    var introOn = g < M.G_ENTRY ? Math.exp(M.RATE * (M.G_ENTRY - g)) - 1 : 0;
    gray.fill(0);
    var sig = 0.57 * scale, inv = 1 / (2 * sig * sig), R = Math.ceil(1.6 * sig);
    for (var k = 0; k < N; k++) {
      var ph = PH[k], x0 = PX[k], y0 = PY[k];
      var mv = 2.5 * Math.sin(t + ph) + Math.sin(t + x0 * 0.003 - y0 * 0.005);
      var wx = x0 - 240 + (m !== 0 ? m * OFF[k] : 0) - M.W / 2;
      var wy = y0 - 135 - M.H / 2;
      var z = HGT[k] + mv;
      var sx = M.r00 * wx + M.r01 * wy + M.r02 * z + M.W / 2 + 0.4 * Math.sin(t + ph * 0.7);
      var sy = M.r10 * wx + M.r11 * wy + M.r12 * z + M.H / 2;
      if (exitOn) sx += EB[k] * exitOn;
      if (introOn) sx -= IB[k] * introOn;
      var cx = sx * scale + ox, cy = sy * scale + oy;
      if (cx < -R || cy < -R || cx > cw + R || cy > ch + R) continue;
      var bx = Math.floor(cx), by = Math.floor(cy);
      for (var dy = -R; dy <= R; dy++) {
        var yy = by + dy; if (yy < 0 || yy >= ch) continue;
        var ddy = yy - cy, row = yy * cw;
        for (var dx = -R; dx <= R; dx++) {
          var xx = bx + dx; if (xx < 0 || xx >= cw) continue;
          var ddx = xx - cx;
          var v = 230 * Math.exp(-(ddx * ddx + ddy * ddy) * inv);
          if (v < 3) continue;
          var o = row + xx;
          if (v > gray[o]) gray[o] = v;
        }
      }
    }
    for (var i = 0, n = gray.length; i < n; i++) {
      var s = gray[i];
      u32[i] = 0xFF000000 | (s << 16) | (s << 8) | s;     /* little-endian ABGR */
    }
    ctx.putImageData(imgData, 0, 0);
  }

  function frame(now) {
    if (!t0) t0 = now;
    draw(((now - t0) / 1000) % LOOP);
    raf = requestAnimationFrame(frame);
  }
  function allowed() { return !reduced.matches && !(conn && conn.saveData); }
  function update() {
    if (!ready) return;
    var run = allowed() && !document.hidden && vis;
    if (run && !raf) { t0 = 0; raf = requestAnimationFrame(frame); canvas.classList.add('is-ready'); }
    else if (!run && raf) { cancelAnimationFrame(raf); raf = 0; }
  }

  var img = new Image();
  img.onload = function () { decode(img); resize(); update(); };
  img.onerror = function () { console.warn('[aegis-terrain] data image failed to decode'); };
  if ('IntersectionObserver' in window) {
    new IntersectionObserver(function (e) {
      near = e[0].isIntersecting;
      if (near && !img.src) img.src = DATA_URI;
    }, { rootMargin: '300px' }).observe(section);
    new IntersectionObserver(function (e) { vis = e[0].isIntersecting; update(); },
      { threshold: [0, 0.01] }).observe(section);
  } else { near = vis = true; img.src = DATA_URI; }
  window.addEventListener('resize', function () { if (ready) { resize(); } });
  document.addEventListener('visibilitychange', update);
  if (reduced.addEventListener) reduced.addEventListener('change', update);
})();
